//! This file is generated by `tools/generate/block_movement.py`.

/// Tag and class flags.
pub mod flag {
    pub const CLIMBABLE: u16 = 1 << 0;
    pub const FENCE: u16 = 1 << 1;
    pub const WALL: u16 = 1 << 2;
    pub const CAN_GLIDE_THROUGH: u16 = 1 << 3;
    pub const SUPPRESSES_BOUNCE: u16 = 1 << 4;
    pub const FENCE_GATE: u16 = 1 << 5;
    pub const TRAPDOOR: u16 = 1 << 6;
    pub const LADDER: u16 = 1 << 7;
}

/// Which fluid a state holds.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FluidKind {
    Empty,
    Water,
    FlowingWater,
    Lava,
    FlowingLava,
}

/// The fluid a state holds and whether it suffocates.
pub struct StateTraits {
    pub fluid: FluidKind,
    /// The fluid's level, eight for a source.
    pub amount: u8,
    /// A flowing fluid falling from above.
    pub falling: bool,
    /// `FluidState.getOwnHeight`, as raw `f32` bits.
    pub own_height: u32,
    pub source: bool,
    pub suffocating: bool,
}

/// One block's movement properties.
pub struct BlockMovement {
    /// The four factors as raw `f32` bits.
    pub friction: u32,
    pub speed_factor: u32,
    pub jump_factor: u32,
    pub bounce_restitution: u32,
    pub flags: u16,
    /// Indices into [`STATE_TRAITS`]: one for every state, or one per state.
    pub states: &'static [u16],
}

